import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, nowIso, rowToJob, type Job, type JobRow } from './db.ts';

interface FieldError {
  field: string;
  message: string;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const ALLOWED_KEYS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_RE = /^[A-Za-z0-9_-]{1,128}$/;

const insertStmt = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed,
     idempotency_key, payload, next_run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const heartbeatStmt = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1');

function sendJson(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(
  res: ServerResponse,
  status: number,
  code: string,
  message: string,
  fields?: FieldError[],
): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on('data', (chunk: Buffer) => chunks.push(chunk));
    req.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function checkInteger(
  obj: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  min: number,
  max: number,
  fallback: number,
  fields: FieldError[],
): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

/** Validates the request and collects every problem before rejecting. */
function validate(
  raw: string,
  contentType: string | undefined,
  idemHeader: string | string[] | undefined,
): { payload: Payload; fields: FieldError[] } {
  const fields: FieldError[] = [];
  const payload: Payload = { input: '', steps: 5, failAttempts: 0 };

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  let parsed: unknown;
  let parsedOk = false;
  try {
    parsed = JSON.parse(raw);
    parsedOk = true;
  } catch {
    fields.push({ field: 'body', message: 'Body must be valid JSON' });
  }

  if (parsedOk) {
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      fields.push({ field: 'body', message: 'Body must be a JSON object' });
    } else {
      const obj = parsed as Record<string, unknown>;
      for (const key of Object.keys(obj)) {
        if (!ALLOWED_KEYS.has(key)) fields.push({ field: key, message: 'Unknown field' });
      }
      if (!Object.hasOwn(obj, 'input')) {
        fields.push({ field: 'input', message: 'input is required' });
      } else {
        const v = obj.input;
        if (typeof v !== 'string') {
